{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Levomepromazine, a tricyclic sulfur-containing tertiary amine with a methoxy substituent, has absolute oral bioavailability of 30–70% in humans, directly supporting F ≥20% for the structurally related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Promethazine, a tricyclic phenothiazine with a dimethylaminoalkyl side chain, has absolute oral bioavailability of 25% versus IV in healthy volunteers, above the 20% threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Imipramine, a tricyclic dibenzazepine with a dimethylaminopropyl side chain, has absolute oral bioavailability around 40% in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Clomipramine, a chloro-substituted tricyclic antidepressant with a dimethylaminopropyl side chain, has absolute oral bioavailability of 48% (range 36–68%) in healthy volunteers, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Venlafaxine, a smaller flexible tertiary amine, has absolute oral bioavailability of 40–45% in healthy young men, supporting high bioavailability for a first-pass-metabolized amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Prothipendyl, a tricyclic thiophenylpyridine with a dimethylaminopropyl side chain, has low absolute bioavailability in healthy volunteers, providing contradictory evidence; its lower structural transferability limits its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Aniracetam has extremely low oral bioavailability in humans due to extensive metabolism, but it lacks the basic amine and tricyclic sulfur features of the query, so it is weakly contradictory.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is diltiazem, a benzothiazepine calcium-channel blocker. The closest and most numerous human absolute-bioavailability analogues (tricyclic sulfur/amine drugs such as levomepromazine, promethazine, imipramine, clomipramine) cluster at 25–50%, all above the 20% threshold; the few low-bioavailability analogues are structurally less transferable. Thus the query is predicted high (F ≥20%).",
  "evidence_gaps": [
    "No direct diltiazem bioavailability record is present in the evidence set; all analogues have Morgan similarity below 0.35.",
    "First-pass metabolism and formulation effects can shift F, but the threshold is low enough that the 25–50% analogue range is decisive."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

